package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity@Table(name="spms_commitment_section",uniqueConstraints=@UniqueConstraint(name="uk_spms_commitment_section_order",columnNames={"agency_id","commitment_version_id","display_order"}))public class PerformanceCommitmentSection extends RspAuditedEntity{@Column(name="commitment_version_id",nullable=false,length=36)private String commitmentVersionId;@Column(name="source_section_id",nullable=false,length=36)private String sourceSectionId;@Column(name="section_type",nullable=false,length=20)private String sectionType;@Column(name="section_code",nullable=false,length=80)private String sectionCode;@Column(nullable=false,length=200)private String title;@Column(length=2000)private String description;@Column(name="weight_percent",nullable=false,precision=7,scale=4)private BigDecimal weightPercent;@Column(name="display_order",nullable=false)private int displayOrder;protected PerformanceCommitmentSection(){}public PerformanceCommitmentSection(String a,String v,PerformanceTemplateSection s){super(a);commitmentVersionId=v;sourceSectionId=s.getId();sectionType=s.getType().name();sectionCode=s.getCode();title=s.getTitle();description=s.getDescription();weightPercent=s.getWeightPercent();displayOrder=s.getDisplayOrder();}public String getCommitmentVersionId(){return commitmentVersionId;}public String getSourceSectionId(){return sourceSectionId;}public String getSectionType(){return sectionType;}public String getSectionCode(){return sectionCode;}public String getTitle(){return title;}public String getDescription(){return description;}public BigDecimal getWeightPercent(){return weightPercent;}public int getDisplayOrder(){return displayOrder;}}
